//! Native NEAR game authority. No fixture issuer, browser-supplied save or reward.
#[path = "../../near/src/kernel.rs"]
mod kernel;
mod transfer_burn;
use kernel::{State,encode_state,initialize,validate_kit,max_points,decode_trace,decode_certificate,transition,history};
use near_sdk::{near,env,require,AccountId,NearToken,Gas,Promise,PromiseOrValue,PanicOnDefault,collections::LookupMap,json_types::{U128,Base64VecU8},serde_json::{json,Value}};
use near_contract_standards::{fungible_token::{FungibleToken,FungibleTokenCore,FungibleTokenResolver,events::{FtMint,FtBurn},metadata::{FungibleTokenMetadata,FungibleTokenMetadataProvider}},non_fungible_token::{NonFungibleToken,Token,TokenId,core::NonFungibleTokenCore,approval::NonFungibleTokenApproval,enumeration::NonFungibleTokenEnumeration,metadata::{NFTContractMetadata,NonFungibleTokenMetadataProvider,TokenMetadata},events::NftMint},storage_management::{StorageManagement,StorageBalance,StorageBalanceBounds}};
const UNIT:u128=1_000_000;const PRICE:u128=250*UNIT;const PRESSURE:u128=50_000*UNIT;const CAPACITY:u128=30_000*UNIT;const WINDOW:u64=900;const STORAGE:u128=100_000_000_000_000_000_000_000;const MIN_FEE:u128=20_000_000_000_000_000_000_000;
fn get<T>(r:kernel::R<T>)->T{r.unwrap_or_else(|e|env::panic_str(e))}
fn now()->u64{env::block_timestamp()/1_000_000_000}
fn hash(data:&[u8])->[u8;32]{env::keccak256(data).try_into().unwrap()}
fn hx(bytes:&[u8])->String{format!("0x{}",hex::encode(bytes))}
fn bytes(s:&str)->Vec<u8>{require!(s.starts_with("0x")&&s[2..].bytes().all(|b|b.is_ascii_digit()||(b'a'..=b'f').contains(&b)),"canonical hex");hex::decode(&s[2..]).unwrap_or_else(|_|env::panic_str("hex bytes"))}
fn bytes32(s:&str)->[u8;32]{bytes(s).try_into().unwrap_or_else(|_|env::panic_str("bytes32"))}
fn nonzero(s:&str)->[u8;32]{let b=bytes32(s);require!(b!=[0;32],"zero ID");b}
fn decimal(s:&str)->u128{require!(!s.is_empty()&&s.len()<=39&&s.bytes().all(|b|b.is_ascii_digit())&&(s=="0"||!s.starts_with('0')),"canonical decimal");s.parse().unwrap_or_else(|_|env::panic_str("amount overflow"))}
fn id(s:&str){require!(decimal(s)>0&&s.len()<=20,"token ID");}
fn refund(who:AccountId,n:u128){if n>0{Promise::new(who).transfer(NearToken::from_yoctonear(n)).detach();}}
fn charge(before:u64,deposit:u128,who:AccountId)->u128{let delta=env::storage_usage().saturating_sub(before);let cost=env::storage_byte_cost().as_yoctonear()*u128::from(delta);require!(deposit>=cost,"attach storage deposit");refund(who,deposit-cost);cost}
#[near(serializers=[borsh])]
#[derive(Clone)]
struct Life {s:State,name:String,revision:u32,attempts:u32,purse:u128,nonce:u64,pending:Option<String>}
#[near(serializers=[borsh])]
#[derive(Clone)]
struct Request {token_id:String,player:AccountId,base_revision:u32,day:u32,kit:u64,shipping:bool,accepted:u64,deadline:u64,seed:[u8;32],decision:[u8;32],base_hash:[u8;32],pressure:u128,reserve:u128,status:u8,processing_fee:u128,multiplier:u16,storage_reserve:u128}
#[near(serializers=[borsh])]
#[derive(Clone)]
struct Record {request_id:String,seed:[u8;32],state_hash:[u8;32],trace_hash:[u8;32],certificate_hash:[u8;32],commitment:[u8;32],reward:u128,history:Vec<u8>}
#[near(serializers=[borsh])]
#[derive(Clone)]
struct Operation {method:String,fingerprint:[u8;32],token_id:String,amount:u128}
#[near(serializers=[json])]
#[serde(rename_all="camelCase")]
pub struct Admission {pub id:String,pub player:AccountId,pub token_id:String,pub base_revision:u32,pub kit_mask:String,pub shipping:bool,pub processing_fee:String,pub multiplier:u16,pub expires_at:String,pub decision_config:String}
#[near(contract_state)]
#[derive(PanicOnDefault)]
pub struct Contract {nft:NonFungibleToken,ft:FungibleToken,lives:LookupMap<TokenId,Life>,requests:LookupMap<String,Request>,records:LookupMap<String,Record>,operations:LookupMap<String,Operation>,owner:AccountId,relayer:AccountId,quote_key:[u8;32],mint_price:u128,min_fee:u128,multiplier:u16,paused:bool,decision:[u8;32],metadata_base:String,next:u64,issued:u128,burns:u128,unregister_burns:u128,allocated:u128,available:u128,reserved:u128,refill_carry:u128,refill_at:u64,native_fees:u128,native_storage_reserved:u128,relay_funding:Option<u128>}
#[near]
impl Contract{
 #[init]
 pub fn new(owner_id:AccountId,relayer_id:AccountId,quote_public_key:Base64VecU8,native_mint_price:U128,decision_config:String,metadata_base:String)->Self{
  require!(env::current_account_id().as_str().ends_with(".testnet"),"testnet contract only");require!(metadata_base.starts_with("https://")&&metadata_base.len()<=200&&!metadata_base.ends_with('/'),"metadata origin");require!(native_mint_price.0>=STORAGE,"mint storage coverage");let key:[u8;32]=quote_public_key.0.try_into().unwrap_or_else(|_|env::panic_str("quote public key"));require!(key!=[0;32],"quote key");
  let vault=env::current_account_id();let mut ft=FungibleToken::new(b"f".to_vec());ft.internal_register_account(&vault);
  Self{nft:NonFungibleToken::new(b"n".to_vec(),owner_id.clone(),None::<Vec<u8>>,Some(b"e".to_vec()),Some(b"a".to_vec())),ft,lives:LookupMap::new(b"l"),requests:LookupMap::new(b"q"),records:LookupMap::new(b"d"),operations:LookupMap::new(b"o"),owner:owner_id,relayer:relayer_id,quote_key:key,mint_price:native_mint_price.0,min_fee:MIN_FEE,multiplier:2,paused:false,decision:nonzero(&decision_config),metadata_base,next:0,issued:0,burns:0,unregister_burns:0,allocated:0,available:CAPACITY,reserved:0,refill_carry:0,refill_at:now(),native_fees:0,native_storage_reserved:0,relay_funding:None}
 }
 pub fn config(&self)->Value{json!({"network_id":"near-testnet","contract_id":env::current_account_id(),"owner_id":self.owner,"relayer_id":self.relayer,"quote_public_key":Base64VecU8(self.quote_key.to_vec()),"rules_hash":hx(&hash(b"nearlyhuman-v2-kernel-2")),"decision_config":hx(&self.decision),"native_mint_price":self.mint_price.to_string(),"token_mint_price_micro":PRICE.to_string(),"storage_deposit":STORAGE.to_string(),"min_processing_fee":self.min_fee.to_string(),"multiplier":self.multiplier,"admissions_paused":self.paused,"issued":self.issued.to_string(),"nft_mint_burns":self.burns.to_string(),"unregister_burns":self.unregister_burns.to_string(),"total_allocated":self.allocated.to_string(),"available":self.available.to_string(),"reserved":self.reserved.to_string(),"native_fees":self.native_fees.to_string(),"native_storage_reserved":self.native_storage_reserved.to_string(),"nft_transfer_call_enabled":false,"transfer_burn_enabled":self.transfer_burn_enabled(),"transfer_burn_bps":50,"total_transfer_burned":self.total_transfer_burned().0.to_string(),"transfer_call_reserved":self.transfer_call_reserved().to_string(),"transfer_call_pending":self.transfer_call_pending()})}
 pub fn life(&self,token_id:TokenId)->Option<Value>{self.lives.get(&token_id).map(|l|json!({"token_id":token_id,"owner_id":self.actual_owner(&token_id),"name":l.name,"state":hx(&encode_state(&l.s)),"revision":l.revision,"attempts":l.attempts,"purse_micro":l.purse.to_string(),"purse_nonce":l.nonce.to_string(),"pending_request":l.pending,"appearance_seed":hx(&l.s.seed)}))}
 pub fn life_raw(&self,token_id:TokenId)->Option<String>{self.lives.get(&token_id).map(|l|hx(&encode_state(&l.s)))}
 pub fn request(&self,request_id:String)->Option<Value>{nonzero(&request_id);self.requests.get(&request_id).map(|q|json!({"request_id":request_id,"token_id":q.token_id,"player":q.player,"base_revision":q.base_revision,"day":q.day,"kit_mask":q.kit.to_string(),"shipping":q.shipping,"accepted_at":q.accepted.to_string(),"deadline":q.deadline.to_string(),"day_seed":hx(&q.seed),"decision_config":hx(&q.decision),"base_hash":hx(&q.base_hash),"pressure":q.pressure.to_string(),"reserved_reward":q.reserve.to_string(),"status":q.status,"processing_fee":q.processing_fee.to_string(),"multiplier":q.multiplier}))}
 pub fn get_request(&self,request_id:String)->Option<Value>{self.request(request_id)}
 pub fn day_record(&self,token_id:TokenId,day:u32)->Option<Value>{self.records.get(&format!("{token_id}:{day}")).map(|r|json!({"request_id":r.request_id,"seed":hx(&r.seed),"state_hash":hx(&r.state_hash),"trace_hash":hx(&r.trace_hash),"certificate_hash":hx(&r.certificate_hash),"replay_commitment":hx(&r.commitment),"reward":r.reward.to_string(),"history":hx(&r.history)}))}
 pub fn quote_day(&self,token_id:TokenId)->Value{let l=self.must_life(&token_id);let maximum=Self::reward(get(max_points(&l.s)),self.issued);json!({"maximum":maximum.to_string(),"pressure":self.issued.to_string(),"capacity":self.capacity().to_string()})}
 pub fn owned_tokens(&self,owner_id:AccountId,cursor:String,limit:u32)->Value{require!((1..=24).contains(&limit),"page limit");let from=decimal(&cursor);let total=self.nft.nft_supply_for_owner(owner_id.clone()).0;if from>=total{return json!({"token_ids":[],"next_cursor":Value::Null})}let tokens=self.nft.nft_tokens_for_owner(owner_id,Some(U128(from)),Some(u64::from(limit)));json!({"token_ids":tokens.iter().map(|t|t.token_id.clone()).collect::<Vec<_>>(),"next_cursor":if from+tokens.len()as u128>=total{Value::Null}else{Value::String((from+tokens.len()as u128).to_string())}})}
 pub fn get_operation(&self,account_id:AccountId,operation_id:String)->Option<Value>{nonzero(&operation_id);self.operations.get(&Self::op_key(&account_id,&operation_id)).map(|o|json!({"method":o.method,"token_id":o.token_id,"request_id":Value::Null,"status":"complete","amount":o.amount.to_string(),"fingerprint":hx(&o.fingerprint)}))}
 pub fn admission_message(&self,admission:Admission)->String{Self::message(&admission)}
 #[payable]
 pub fn mint_nft(&mut self,name:String,stats:[u32;3],operation_id:String,expected_owner:AccountId)->TokenId{let who=env::predecessor_account_id();require!(who==expected_owner,"selected wallet changed");let f=Self::fingerprint("mint_nft",&json!([expected_owner,name,stats]));if let Some(o)=self.repeat(&who,&operation_id,&f){refund(who,env::attached_deposit().as_yoctonear());return o.token_id}require!(!self.paused&&env::attached_deposit().as_yoctonear()==self.mint_price,"mint fee");let before=env::storage_usage();let token=self.birth(who.clone(),name,stats);self.complete(who.clone(),operation_id,"mint_nft",f,token.clone(),0);let cost=env::storage_byte_cost().as_yoctonear()*u128::from(env::storage_usage()-before);require!(self.mint_price>=cost,"mint storage");self.native_fees=self.native_fees.checked_add(self.mint_price-cost).expect("fee overflow");token}
 #[payable]
 pub fn accept_day(&mut self,admission:Admission,signature:Base64VecU8){let a=admission;let t=now();let fee=decimal(&a.processing_fee);let expiry=u64::try_from(decimal(&a.expires_at)).expect("expiry");let kit=u64::try_from(decimal(&a.kit_mask)).expect("kit");nonzero(&a.id);id(&a.token_id);let who=env::predecessor_account_id();require!(!self.paused&&who==a.player&&self.actual_owner(&a.token_id)==who,"owner admission");require!(self.requests.get(&a.id).is_none(),"used admission");let mut l=self.must_life(&a.token_id);require!(l.s.alive&&l.pending.is_none()&&l.revision==a.base_revision,"accepted base");require!(a.multiplier==self.multiplier&&nonzero(&a.decision_config)==self.decision&&expiry>=t&&expiry<=t+WINDOW,"admission changed");require!(fee>=self.min_fee&&env::attached_deposit().as_yoctonear()==fee,"processing fee");let sig:[u8;64]=signature.0.try_into().unwrap_or_else(|_|env::panic_str("quote signature"));require!(env::ed25519_verify(&sig,Self::message(&a).as_bytes(),&self.quote_key),"signed fee");get(validate_kit(&l.s,kit));self.refill();let maximum=if a.shipping{Self::reward(get(max_points(&l.s)),self.issued)}else{0};require!(self.available>=maximum,"shipping busy");let before=env::storage_usage();self.available-=maximum;self.reserved+=maximum;let day=l.s.day.checked_add(1).expect("day overflow");let seed=hash(format!("NEARLYHUMAN_DAY_SEED_V2\nnear-testnet\n{}\n{}\n{day}",env::current_account_id(),hx(&l.s.seed)).as_bytes());let q=Request{token_id:a.token_id.clone(),player:who.clone(),base_revision:l.revision,day,kit,shipping:a.shipping&&maximum>0,accepted:t,deadline:t+WINDOW,seed,decision:self.decision,base_hash:hash(&encode_state(&l.s)),pressure:self.issued,reserve:maximum,status:1,processing_fee:fee,multiplier:a.multiplier,storage_reserve:self.min_fee/2};self.requests.insert(&a.id,&q);l.pending=Some(a.id.clone());l.attempts=l.attempts.checked_add(1).expect("attempt overflow");self.lives.insert(&a.token_id,&l);let cost=env::storage_byte_cost().as_yoctonear()*u128::from(env::storage_usage()-before);require!(fee>=cost+self.min_fee/2,"day storage coverage");self.native_storage_reserved=self.native_storage_reserved.checked_add(q.storage_reserve).expect("storage reserve overflow");self.native_fees=self.native_fees.checked_add(fee-cost-q.storage_reserve).expect("fee overflow");env::log_str(&json!({"standard":"nearlyhuman","version":"2.0.0","event":"day_accepted","data":[{"request_id":a.id,"token_id":a.token_id,"player":who,"day":day,"day_seed":hx(&seed)}]}).to_string());}
 pub fn finalize(&mut self,request_id:String,trace:String,certificate:String,replay_commitment:String){self.relay();nonzero(&request_id);let commitment=nonzero(&replay_commitment);let mut q=self.requests.get(&request_id).expect("request");let mut l=self.must_life(&q.token_id);require!(q.status==1&&now()<=q.deadline&&l.pending.as_deref()==Some(&request_id)&&l.revision==q.base_revision&&hash(&encode_state(&l.s))==q.base_hash,"accepted base");let tr=bytes(&trace);let cert=bytes(&certificate);require!(tr.len()<=4608&&cert.len()<=8192,"bounded replay");let parsed=get(decode_trace(&tr));let witness=decode_certificate(&cert).ok().flatten();let(result,points)=get(transition(l.s.clone(),&parsed,witness.as_ref(),q.seed,q.kit,q.shipping));require!(result.day==q.day,"day result");let amount=Self::reward(points,q.pressure);require!(points==0||amount>0,"zero shipment");require!(amount<=q.reserve,"reserved reward");let before=env::storage_usage();self.refill();self.release(&q,amount);q.status=2;l.s=result;l.revision=l.revision.checked_add(1).expect("revision overflow");l.pending=None;if amount>0{l.purse=l.purse.checked_add(amount).expect("purse overflow");self.allocated=self.allocated.checked_add(amount).expect("allocation overflow");self.issued=self.issued.checked_add(amount).expect("issuance overflow");self.ft.internal_deposit(&env::current_account_id(),amount);FtMint{owner_id:&env::current_account_id(),amount:U128(amount),memo:Some("NPC shipment")}.emit();}let r=Record{request_id:request_id.clone(),seed:q.seed,state_hash:hash(&encode_state(&l.s)),trace_hash:hash(&tr),certificate_hash:hash(&cert),commitment,reward:amount,history:history(&parsed)};self.records.insert(&format!("{}:{}",q.token_id,q.day),&r);self.requests.insert(&request_id,&q);self.lives.insert(&q.token_id,&l);let cost=env::storage_byte_cost().as_yoctonear()*u128::from(env::storage_usage().saturating_sub(before));require!(q.storage_reserve>=cost,"settlement storage coverage");self.native_storage_reserved-=q.storage_reserve;self.native_fees=self.native_fees.checked_add(q.storage_reserve-cost).expect("fee overflow");self.backed();env::log_str(&json!({"standard":"nearlyhuman","version":"2.0.0","event":"day_settled","data":[{"request_id":request_id,"token_id":q.token_id,"day":q.day,"state_hash":hx(&r.state_hash),"reward":amount.to_string(),"replay_commitment":replay_commitment}]}).to_string());}
 pub fn fail(&mut self,request_id:String){self.relay();self.end_attempt(request_id,3,false)}
 pub fn expire(&mut self,request_id:String){self.end_attempt(request_id,4,true)}
 #[payable]
 pub fn withdraw(&mut self,token_id:TokenId,amount:U128,operation_id:String,expected_owner:AccountId){let who=env::predecessor_account_id();require!(who==expected_owner,"selected wallet changed");let f=Self::fingerprint("withdraw",&json!([expected_owner,token_id,amount.0.to_string()]));if self.repeat(&who,&operation_id,&f).is_some(){refund(who,env::attached_deposit().as_yoctonear());return}require!(env::attached_deposit().as_yoctonear()>=STORAGE,"withdraw storage deposit");require!(self.actual_owner(&token_id)==who,"owner purse");let mut l=self.must_life(&token_id);require!(amount.0>0&&l.purse>=amount.0,"purse funds");let before=env::storage_usage();self.register(&who);l.purse-=amount.0;l.nonce=l.nonce.checked_add(1).expect("nonce overflow");self.allocated-=amount.0;self.lives.insert(&token_id,&l);self.taxed_transfer(&env::current_account_id(),&who,amount.0,Some("NFT purse withdrawal".into()));self.complete(who.clone(),operation_id,"withdraw",f,token_id,amount.0);charge(before,env::attached_deposit().as_yoctonear(),who);self.backed();}
 #[payable]
 pub fn birth_from_wallet(&mut self,name:String,stats:[u32;3],operation_id:String,expected_owner:AccountId)->TokenId{let who=env::predecessor_account_id();require!(who==expected_owner,"selected wallet changed");let f=Self::fingerprint("birth_from_wallet",&json!([expected_owner,name,stats]));if let Some(o)=self.repeat(&who,&operation_id,&f){refund(who,env::attached_deposit().as_yoctonear());return o.token_id}require!(!self.paused&&env::attached_deposit().as_yoctonear()>=STORAGE,"birth storage");let before=env::storage_usage();self.ft.internal_withdraw(&who,PRICE);self.burns=self.burns.checked_add(PRICE).expect("burn overflow");let token=self.birth(who.clone(),name,stats);self.complete(who.clone(),operation_id,"birth_from_wallet",f,token.clone(),PRICE);charge(before,env::attached_deposit().as_yoctonear(),who.clone());FtBurn{owner_id:&who,amount:U128(PRICE),memo:Some("NFT birth")}.emit();self.backed();token}
 #[payable]
 pub fn birth_from_purse(&mut self,source_token_id:TokenId,expected_nonce:String,name:String,stats:[u32;3],operation_id:String,expected_owner:AccountId)->TokenId{let who=env::predecessor_account_id();require!(who==expected_owner,"selected wallet changed");let f=Self::fingerprint("birth_from_purse",&json!([expected_owner,source_token_id,expected_nonce,name,stats]));if let Some(o)=self.repeat(&who,&operation_id,&f){refund(who,env::attached_deposit().as_yoctonear());return o.token_id}require!(!self.paused&&env::attached_deposit().as_yoctonear()>=STORAGE,"birth storage");require!(self.actual_owner(&source_token_id)==who,"owner purse");let mut l=self.must_life(&source_token_id);require!(u128::from(l.nonce)==decimal(&expected_nonce)&&l.purse>=PRICE,"purse birth");let before=env::storage_usage();self.ft.internal_withdraw(&env::current_account_id(),PRICE);l.purse-=PRICE;l.nonce=l.nonce.checked_add(1).expect("nonce overflow");self.allocated-=PRICE;self.burns=self.burns.checked_add(PRICE).expect("burn overflow");self.lives.insert(&source_token_id,&l);let token=self.birth(who.clone(),name,stats);self.complete(who.clone(),operation_id,"birth_from_purse",f,token.clone(),PRICE);charge(before,env::attached_deposit().as_yoctonear(),who);FtBurn{owner_id:&env::current_account_id(),amount:U128(PRICE),memo:Some("NFT birth")}.emit();self.backed();token}
 pub fn set_admissions_paused(&mut self,paused:bool){self.admin();self.paused=paused;}
 pub fn set_decision_config(&mut self,decision_config:String){self.admin();require!(self.paused,"pause admissions");require!(self.native_storage_reserved==0,"pending days");let next=nonzero(&decision_config);require!(next!=self.decision,"policy unchanged");let previous=self.decision;self.decision=next;env::log_str(&json!({"standard":"nearlyhuman","version":"2.0.0","event":"decision_config_changed","data":[{"old":hx(&previous),"new":hx(&next)}]}).to_string());}
 pub fn set_fees(&mut self,native_mint_price:U128,min_processing_fee:U128,multiplier:u16){self.admin();require!(native_mint_price.0>=STORAGE&&(MIN_FEE..=STORAGE*2).contains(&min_processing_fee.0)&&(1..=20).contains(&multiplier),"bounded fees");self.mint_price=native_mint_price.0;self.min_fee=min_processing_fee.0;self.multiplier=multiplier;}
 pub fn set_services(&mut self,relayer_id:AccountId,quote_public_key:Base64VecU8){self.admin();let key:[u8;32]=quote_public_key.0.try_into().unwrap_or_else(|_|env::panic_str("quote key"));require!(key!=[0;32],"quote key");self.relayer=relayer_id;self.quote_key=key;}
 pub fn fund_relayer(&mut self,amount:U128)->Promise{require!(env::predecessor_account_id()==self.owner||env::predecessor_account_id()==self.relayer,"funding authority");require!(self.relay_funding.is_none()&&amount.0>0&&amount.0<=self.native_fees,"earned fees");self.relay_funding=Some(amount.0);let rent=env::storage_byte_cost().as_yoctonear()*u128::from(env::storage_usage());require!(env::account_balance().as_yoctonear()>=rent+STORAGE+self.native_storage_reserved+amount.0,"storage reserve");self.native_fees-=amount.0;Promise::new(self.relayer.clone()).transfer(NearToken::from_yoctonear(amount.0)).then(Self::ext(env::current_account_id()).with_static_gas(Gas::from_tgas(10)).on_relayer_funded(amount))}
 #[private]
 pub fn on_relayer_funded(&mut self,amount:U128){require!(env::predecessor_account_id()==env::current_account_id()&&self.relay_funding==Some(amount.0)&&env::promise_results_count()==1,"fund callback");self.relay_funding=None;if env::promise_result_checked(0,0).is_err(){self.native_fees=self.native_fees.checked_add(amount.0).expect("fee overflow");}}
}
impl Contract{
 fn admin(&self){require!(env::predecessor_account_id()==self.owner,"owner only")}
 fn relay(&self){require!(env::predecessor_account_id()==self.relayer,"relayer only")}
 fn must_life(&self,t:&TokenId)->Life{self.lives.get(t).expect("NFT exists")}
 fn actual_owner(&self,t:&TokenId)->AccountId{self.nft.owner_by_id.get(t).expect("NFT exists")}
 fn register(&mut self,who:&AccountId){if self.ft.accounts.get(who).is_none(){self.ft.internal_register_account(who)}}
 fn birth(&mut self,who:AccountId,name:String,stats:[u32;3])->TokenId{let n=name.as_bytes();require!(!n.is_empty()&&n.len()<=8&&n[0]!=b' '&&n[n.len()-1]!=b' '&&n.iter().all(|b|*b==b' '||b.is_ascii_digit()||b.is_ascii_uppercase()),"name");self.next=self.next.checked_add(1).expect("ID overflow");let token=self.next.to_string();let seed=hash(format!("NEARLYHUMAN_BIRTH_V2\nnear-testnet\n{}\n{}\n{}\n{}\n{}",env::current_account_id(),token,who,env::block_timestamp(),hex::encode(env::random_seed())).as_bytes());let s=get(initialize(seed,stats));self.register(&who);self.nft.internal_mint_with_refund(token.clone(),who.clone(),None,None);self.lives.insert(&token,&Life{s,name,revision:0,attempts:0,purse:0,nonce:0,pending:None});NftMint{owner_id:&who,token_ids:&[&token],memo:Some("A little life")}.emit();token}
 fn op_key(who:&AccountId,op:&str)->String{format!("{who}:{op}")}
 fn fingerprint(method:&str,args:&Value)->[u8;32]{hash(format!("{method}\n{args}").as_bytes())}
 fn repeat(&self,who:&AccountId,id:&str,f:&[u8;32])->Option<Operation>{nonzero(id);let found=self.operations.get(&Self::op_key(who,id));if let Some(o)=&found{require!(o.fingerprint==*f,"operation payload changed");}found}
 fn complete(&mut self,who:AccountId,id:String,method:&str,fingerprint:[u8;32],token_id:String,amount:u128){self.operations.insert(&Self::op_key(&who,&id),&Operation{method:method.into(),fingerprint,token_id,amount});}
 fn message(a:&Admission)->String{nonzero(&a.id);id(&a.token_id);decimal(&a.kit_mask);decimal(&a.processing_fee);decimal(&a.expires_at);nonzero(&a.decision_config);format!("NEARLYHUMAN_DAY_V2\nnear-testnet\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}",env::current_account_id(),a.id,a.player,a.token_id,a.base_revision,a.kit_mask,if a.shipping{"1"}else{"0"},a.processing_fee,a.multiplier,a.expires_at,a.decision_config)}
 fn reward(points:u32,pressure:u128)->u128{require!(points<=1360,"shipment bound");u128::from(points)*UNIT*PRESSURE/(10*(PRESSURE+pressure))}
 fn capacity(&self)->u128{let credit=(self.refill_carry+u128::from(now().saturating_sub(self.refill_at))*CAPACITY)/86400;(self.available+credit).min(CAPACITY-self.reserved)}
 fn refill(&mut self){let raw=self.refill_carry+u128::from(now().saturating_sub(self.refill_at))*CAPACITY;let credit=raw/86400;let space=CAPACITY-self.available-self.reserved;if credit>=space{self.available+=space;self.refill_carry=0}else{self.available+=credit;self.refill_carry=raw%86400}self.refill_at=now();}
 fn release(&mut self,q:&Request,amount:u128){require!(amount<=q.reserve,"reserved quote");self.reserved-=q.reserve;self.available+=q.reserve-amount;}
 fn end_attempt(&mut self,request_id:String,status:u8,expired:bool){nonzero(&request_id);let mut q=self.requests.get(&request_id).expect("request");require!(q.status==1&&(!expired||now()>q.deadline),"pending deadline");let mut l=self.must_life(&q.token_id);require!(l.pending.as_deref()==Some(&request_id),"pending life");self.refill();self.release(&q,0);self.native_storage_reserved-=q.storage_reserve;self.native_fees=self.native_fees.checked_add(q.storage_reserve).expect("fee overflow");q.status=status;l.pending=None;self.requests.insert(&request_id,&q);self.lives.insert(&q.token_id,&l);env::log_str(&json!({"standard":"nearlyhuman","version":"2.0.0","event":"day_failed","data":[{"request_id":request_id,"token_id":q.token_id,"status":status}]}).to_string());}
 fn backed(&self){require!(self.ft.accounts.get(&env::current_account_id()).unwrap_or(0)>=self.allocated.checked_add(self.transfer_call_reserved()).expect("reserved backing overflow"),"backed purses")}
 fn decorated(&self,mut t:Token)->Token{if let Some(l)=self.lives.get(&t.token_id){let query=format!("networkId=near-testnet&collection={}",env::current_account_id());t.metadata=Some(TokenMetadata{title:Some(format!("{} #{}",l.name,t.token_id)),description:Some(format!("NEARlyHuman · Day {} · {}",l.s.day,if l.s.alive{"a life of its own"}else{"remembered"})),media:Some(format!("{}/api/near/v2/nft/{}/image.svg?{}",self.metadata_base,t.token_id,query)),reference:Some(format!("{}/api/near/v2/nft/{}?{}",self.metadata_base,t.token_id,query)),copies:Some(1),..TokenMetadata::default()});}t}
 fn transfer_guard(&self,id:&TokenId){require!(self.must_life(id).pending.is_none(),"day pending")}
}
#[near]
impl NonFungibleTokenCore for Contract{
 #[payable]
 fn nft_transfer(&mut self,receiver_id:AccountId,token_id:TokenId,approval_id:Option<u64>,memo:Option<String>){self.transfer_guard(&token_id);self.nft.nft_transfer(receiver_id,token_id.clone(),approval_id,memo);let mut l=self.must_life(&token_id);l.nonce=l.nonce.checked_add(1).expect("nonce overflow");l.revision=l.revision.checked_add(1).expect("revision overflow");self.lives.insert(&token_id,&l);}
 #[payable]
 fn nft_transfer_call(&mut self,receiver_id:AccountId,token_id:TokenId,approval_id:Option<u64>,memo:Option<String>,msg:String)->PromiseOrValue<bool>{let _=(receiver_id,token_id,approval_id,memo,msg);env::panic_str("NFT transfer-call is not enabled; use direct NFT transfer")}
 fn nft_token(&self,token_id:TokenId)->Option<Token>{self.nft.nft_token(token_id).map(|t|self.decorated(t))}
}
